import fs from "node:fs";
const root = process.argv[2];
const prefix = process.argv[3] ?? "paired";
const rounds = Number(process.argv[4] ?? "3");
const pattern = new RegExp("^" + prefix + "-(.+)-(\\d+)-(baseline|candidate)\\.log$");
const files = fs.readdirSync(root);
const whole = [], lanes = [];
for (const name of files) {
  const m = name.match(pattern);
  if (!m) continue;
  const fixture = m[1], round = Number(m[2]), variant = m[3];
  const contents = fs.readFileSync(root + "/" + name, "utf8");
  if (["selected", "chord", "radial", "contacts"].includes(fixture) &&
      !contents.includes("test result: ok. 1 passed; 0 failed; 0 ignored;"))
    throw new Error("Incomplete test: " + name);
  const time = root + "/" + name.replace(/\.log$/, ".time");
  if (fs.existsSync(time)) {
    const values = Object.fromEntries([...fs.readFileSync(time, "utf8").matchAll(/(\w+)=([0-9.]+)/g)].map(m => [m[1], Number(m[2])]));
    if (values.exit !== 0) throw new Error("Unsuccessful process: " + name);
    whole.push({fixture, round, variant, ...values});
  }
  for (const line of contents.split("\n")) {
    let m = line.match(/^([^:]+): (\d+) (?:iterations|curves) in ([0-9.]+)(ns|µs|ms|s) /);
    if (m) {
      const iterations = Number(m[2]), total_ns = Number(m[3]) * ({ns:1,"µs":1000,ms:1000000,s:1000000000})[m[4]];
      lanes.push({fixture, round, variant, name:m[1], iterations, total_ns, ns_per_iter:total_ns/iterations, output:line});
      continue;
    }
    m = line.match(/^([^:]+): (\d+) iterations, total_ns=(\d+), ns_per_iter=(\d+),/);
    if (m) {
      const iterations = Number(m[2]), total_ns = Number(m[3]);
      lanes.push({fixture, round, variant, name:m[1], iterations, total_ns, ns_per_iter:total_ns/iterations, output:line});
    }
  }
}
const median = xs => { const sorted = xs.toSorted((a,b)=>a-b); return sorted[(sorted.length-1)/2]; };
const compare = (rows, key, value) => [...new Set(rows.map(key))].map(name => {
  const baseline = rows.filter(r => key(r) === name && r.variant === "baseline").map(r=>r[value]);
  const candidate = rows.filter(r => key(r) === name && r.variant === "candidate").map(r=>r[value]);
  if (baseline.length !== rounds || candidate.length !== rounds) throw new Error("Unpaired " + name);
  const before = median(baseline), after = median(candidate);
  return {name, baseline, candidate, baseline_median:before, candidate_median:after, change_percent:100*(after/before-1)};
});
const instructions = ["rectangles","circles","capsules"].map(fixture => {
  const values = ["baseline","candidate"].map(variant => {
    const contents = fs.readFileSync(root+"/instructions-"+fixture+"-"+variant+".callgrind","utf8");
    const summary = Number(contents.match(/^summary: (\d+)$/m)?.[1]);
    const total = Number(contents.match(/^totals: (\d+)$/m)?.[1]);
    if (!summary || summary !== total) throw new Error("Incomplete Callgrind result");
    return summary;
  });
  return {fixture, baseline:values[0], candidate:values[1], change_percent:100*(values[1]/values[0]-1)};
});
console.log(JSON.stringify({
  cpu:7, alternating_order:Array.from({length:rounds}, (_, index) => index % 2 ? "candidate,baseline" : "baseline,candidate"),
  invocations:files.filter(f=>pattern.test(f)).length,
  whole_process_measurements:whole,
  whole_process_summary:compare(whole,r=>r.fixture,"elapsed_s"),
  lane_measurements:lanes,
  lane_summary:compare(lanes,r=>r.fixture+"/"+r.name,"ns_per_iter").sort((a,b)=>b.change_percent-a.change_percent),
  instructions
}, null, 2));

reproduction.streaming_counter:
// Local evidence tool: streaming accounting for Heaptrack 1.5 raw format 3.
// It does not symbolize or intern (size, trace) pairs; retained state is bounded
// by trace definitions and currently live allocations, not allocation history.
#include <algorithm>
#include <array>
#include <charconv>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <limits>
#include <stdexcept>
#include <string>
#include <unordered_map>
#include <vector>

using U = std::uint64_t;
struct Trace { U ip, parent, calls = 0, bytes = 0, temporary = 0; };
struct Allocation { U size, trace; };

U number(const std::string& line, std::size_t& cursor) {
    while (cursor < line.size() && line[cursor] == ' ') ++cursor;
    U value = 0;
    const auto result = std::from_chars(line.data() + cursor,
                                        line.data() + line.size(), value, 16);
    if (result.ec != std::errc{}) throw std::runtime_error("invalid hex field");
    cursor = result.ptr - line.data();
    return value;
}
void add(U& total, U value) {
    if (value > std::numeric_limits<U>::max() - total)
        throw std::runtime_error("counter overflow");
    total += value;
}

int main() {
    std::ios::sync_with_stdio(false);
    std::vector<Trace> traces(1);
    std::unordered_map<U, Allocation> live;
    live.reserve(16384);
    std::vector<std::string> modules;
    std::array<U, 256> modes{};
    U allocations = 0, frees = 0, unknown_frees = 0, temporary = 0;
    U traffic = 0, heap = 0, peak = 0, peak_blocks = 0, last = 0;
    U page_size = 0, peak_rss_pages = 0, duration_ms = 0, lines = 0;
    bool version = false;
    std::string line;
    try {
        while (std::getline(std::cin, line)) {
            ++lines;
            if (line.empty()) throw std::runtime_error("empty record");
            const auto mode = static_cast<unsigned char>(line[0]);
            ++modes[mode];
            std::size_t cursor = 1;
            switch (mode) {
            case 'v':
                (void)number(line, cursor);
                if (number(line, cursor) != 3 || version || lines != 1)
                    throw std::runtime_error("expected one format-3 header");
                version = true;
                break;
            case 't': {
                const U ip = number(line, cursor), parent = number(line, cursor);
                if (!version || parent >= traces.size())
                    throw std::runtime_error("invalid trace parent");
                traces.push_back({ip, parent});
                break;
            }
            case '+': {
                const U size = number(line, cursor), trace = number(line, cursor);
                const U pointer = number(line, cursor);
                if (!version || trace == 0 || trace >= traces.size() || pointer == 0)
                    throw std::runtime_error("invalid allocation");
                if (!live.emplace(pointer, Allocation{size, trace}).second)
                    throw std::runtime_error("duplicate live pointer");
                add(allocations, 1);
                add(traffic, size);
                add(heap, size);
                peak = std::max(peak, heap);
                peak_blocks = std::max(peak_blocks, static_cast<U>(live.size()));
                add(traces[trace].calls, 1);
                add(traces[trace].bytes, size);
                last = pointer;
                break;
            }
            case '-': {
                const U pointer = number(line, cursor);
                const bool is_temporary = last == pointer;
                last = 0;
                const auto found = live.find(pointer);
                if (found == live.end()) {
                    add(unknown_frees, 1);
                    break;
                }
                if (is_temporary) {
                    add(temporary, 1);
                    add(traces[found->second.trace].temporary, 1);
                }
                if (found->second.size > heap)
                    throw std::runtime_error("heap underflow");
                heap -= found->second.size;
                live.erase(found);
                add(frees, 1);
                break;
            }
            case 'I':
                page_size = number(line, cursor);
                (void)number(line, cursor);
                break;
            case 'R':
                peak_rss_pages = std::max(peak_rss_pages, number(line, cursor));
                break;
            case 'c':
                duration_ms = std::max(duration_ms, number(line, cursor));
                break;
            case 'm':
                modules.push_back(line);
                break;
            case 'x': case 'X': case '#':
                break;
            default:
                throw std::runtime_error("unsupported raw record mode");
            }
        }
        if (!std::cin.eof() || !version)
            throw std::runtime_error("incomplete input read");
        U live_sum = 0;
        for (const auto& [pointer, allocation] : live) add(live_sum, allocation.size);
        if (live_sum != heap || allocations - frees != live.size())
            throw std::runtime_error("final live-state invariant failed");
        std::vector<std::size_t> order;
        for (std::size_t i = 1; i < traces.size(); ++i)
            if (traces[i].calls) order.push_back(i);
        std::sort(order.begin(), order.end(), [&](auto a, auto b) {
            if (traces[a].calls != traces[b].calls) return traces[a].calls > traces[b].calls;
            return a < b;
        });
        std::cout << "{\n\"format\":3,\"records\":" << lines
                  << ",\"allocations\":" << allocations << ",\"frees\":" << frees
                  << ",\"untracked_frees\":" << unknown_frees
                  << ",\"temporary_allocations\":" << temporary
                  << ",\"allocated_bytes\":" << traffic
                  << ",\"peak_live_bytes\":" << peak
                  << ",\"end_live_bytes\":" << heap
                  << ",\"peak_live_allocations\":" << peak_blocks
                  << ",\"end_live_allocations\":" << live.size()
                  << ",\"trace_count\":" << traces.size() - 1
                  << ",\"duration_ms\":" << duration_ms
                  << ",\"page_size\":" << page_size
                  << ",\"recorded_peak_rss_pages\":" << peak_rss_pages
                  << ",\n\"record_counts\":{";
        bool comma = false;
        for (std::size_t i = 0; i < modes.size(); ++i) if (modes[i]) {
            if (comma) std::cout << ',';
            comma = true;
            std::cout << std::quoted(std::string(1, static_cast<char>(i))) << ':' << modes[i];
        }
        std::cout << "},\n\"module_records\":[";
        for (std::size_t i = 0; i < modules.size(); ++i) {
            if (i) std::cout << ',';
            std::cout << std::quoted(modules[i]);
        }
        std::cout << "],\n\"top_allocation_traces\":[";
        order.resize(std::min<std::size_t>(32, order.size()));
        for (std::size_t rank = 0; rank < order.size(); ++rank) {
            if (rank) std::cout << ',';
            auto index = order[rank];
            const auto& trace = traces[index];
            std::cout << "\n{\"trace\":" << index << ",\"allocations\":" << trace.calls
                      << ",\"bytes\":" << trace.bytes << ",\"temporary\":" << trace.temporary
                      << ",\"ips\":[";
            bool separated = false;
            while (index) {
                if (separated) std::cout << ',';
                separated = true;
                std::cout << '"' << std::hex << traces[index].ip << std::dec << '"';
                index = traces[index].parent;
            }
            std::cout << "]}";
        }
        std::cout << "],\n\"trace_table\":[";
        for (std::size_t i = 0; i < traces.size(); ++i) {
            if (i) std::cout << ',';
            const auto& trace = traces[i];
            std::cout << "\n[\"" << std::hex << trace.ip << std::dec << "\","
                      << trace.parent << ',' << trace.calls << ','
                      << trace.bytes << ',' << trace.temporary << ']';
        }
        std::cout << "]\n}\n";
    } catch (const std::exception& error) {
        std::cerr << "Raw accounting rejected input at line " << lines
                  << ": " << error.what() << '\n';
        return 1;
    }
}

reproduction.allocation_attribution:
import fs from "node:fs";
const profile = JSON.parse(fs.readFileSync(process.argv[2], "utf8"));
const module = profile.module_records.find(line => /^m \S+ x /.test(line));
if (!module) throw new Error("No executable mapping");
const base = BigInt("0x" + module.split(" ")[3]);
const groups = [];
for (const line of fs.readFileSync(process.argv[3], "utf8").split("\n")) {
    const match = line.match(/^([0-9a-f]+)\s+([0-9a-f]+)\s+[tTwW]\s+(.+)$/);
    if (!match) continue;
    const start = parseInt(match[1], 16), size = parseInt(match[2], 16), name = match[3];
    let group = groups.at(-1);
    if (!group || group.start !== start) {
        group = {start, end: start + size, names: []};
        groups.push(group);
    }
    group.end = Math.max(group.end, start + size);
    if (!group.names.includes(name)) group.names.push(name);
}
const resolve = ip => {
    const relative = BigInt("0x" + ip) - base;
    if (relative < 0n || relative > 0xffffffffn) return -1;
    const offset = Number(relative) - 1;
    let low = 0, high = groups.length;
    while (low < high) {
        const middle = (low + high) >>> 1;
        if (groups[middle].start <= offset) low = middle + 1;
        else high = middle;
    }
    const index = low - 1;
    return index >= 0 && offset < groups[index].end ? index : -1;
};
const traceGroups = profile.trace_table.map(trace => resolve(trace[0]));
const inclusive = new Map(), nearestExact = new Map(), nearestCurve = new Map();
const exactGroup = groups.map(g => g.names.some(name => /<?(?:hyperreal|hypersolve|hypercurve|hyperlimit|hyperlattice|hypertri)::/.test(name)));
const curveGroup = groups.map(g => g.names.some(name => /<?hypercurve::/.test(name)));
const add = (map, group, trace) => {
    if (group < 0) return;
    let value = map.get(group);
    if (!value) {
        value = {allocations: 0, bytes: 0, temporary: 0};
        map.set(group, value);
    }
    value.allocations += trace[2];
    value.bytes += trace[3];
    value.temporary += trace[4];
};
let allocations = 0, bytes = 0, temporary = 0;
for (let index = 1; index < profile.trace_table.length; ++index) {
    const trace = profile.trace_table[index];
    allocations += trace[2]; bytes += trace[3]; temporary += trace[4];
    if (!trace[2]) continue;
    const seen = new Set();
    let exact = -1, curve = -1;
    for (let ancestor = index; ancestor; ancestor = profile.trace_table[ancestor][1]) {
        const group = traceGroups[ancestor];
        if (group < 0 || seen.has(group)) continue;
        seen.add(group);
        add(inclusive, group, trace);
        if (exact < 0 && exactGroup[group]) exact = group;
        if (curve < 0 && curveGroup[group]) curve = group;
    }
    add(nearestExact, exact, trace);
    add(nearestCurve, curve, trace);
}
if (allocations !== profile.allocations || bytes !== profile.allocated_bytes ||
    temporary !== profile.temporary_allocations)
    throw new Error("Trace-table totals disagree with raw event accounting");
const rows = map => [...map].map(([index, value]) => ({
    ...value, allocation_percent: value.allocations * 100 / allocations,
    start: groups[index].start, names: groups[index].names
})).sort((a, b) => b.allocations - a.allocations);
const summary = {...profile};
delete summary.trace_table;
delete summary.top_allocation_traces;
console.log(JSON.stringify({
    summary,
    method: "Each symbol-address group is counted at most once per allocation stack; aliases at the same address stay grouped. Inlined source frames are unavailable in this optimized artifact.",
    inclusive: rows(inclusive), nearest_exact_stack_owner: rows(nearestExact),
    nearest_hypercurve_owner: rows(nearestCurve)
}, null, 2));
